// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, address to, uint256 amount, bool shouldFail) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        FailingToken tok = new FailingToken();
        tok.setShouldFail(shouldFail);

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory vs = new uint256[](1);
        vs[0] = amount;

        bool ok;
        try c.transfer(from, address(tok), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: transfer succeeds only if the token accepted the transferFrom.
        assertTrue(ok == !shouldFail);
    }
}

contract FailingToken {
    bool public shouldFail;

    function setShouldFail(bool b) external { shouldFail = b; }

    function transferFrom(address, address, uint256) external returns (bool) {
        if (shouldFail) revert();
        return true;
    }
}
